import{z as n,x as i,o as B,c as d,q as o,j as r,D as e,d as A,s as l,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"算法基准的方法","description":"","frontmatter":{"title":"算法基准的方法","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ae-benchmark-method.md","filePath":"cs/ae-benchmark-method.md","lastUpdated":1791413859000}'),p={name:"cs/ae-benchmark-method.md"};function m(C,E,c,D,h,F){const t=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=o('<h1 id="算法基准的方法" tabindex="-1">算法基准的方法 <a class="header-anchor" href="#算法基准的方法" aria-label="Permalink to &quot;算法基准的方法&quot;">​</a></h1><div class="epigraph"><p>一个不带方差的数字不是测量，是轶事；算法比较输给环境变量的次数，比输给彼此的次数多。</p><footer>—— 据 Mytkowicz et al., ASPLOS 2009；Georges, Buytaert, and Eeckhout, OOPSLA 2007 整理</footer></div><p><a href="/cs/ae-randomized-practice">上一课</a>把随机算法的验证押在「同一组种子配对」上；配对为什么减方差、除此之外还要钉住什么，本课给全课程的验证纪律：怎么测一个算法改动，结论才配写进代码评审。前四课的每个杠杆——选型、常数、布局、位运算、随机化——最后都由这里的数字裁决。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基准的噪声源比被比较的差距还大：CPU 频率迁移、缓存与分支预测器的状态残留、后台任务，乃至环境变量表的大小与链接顺序——2009 年那篇 ASPLOS 论文证明这些「明显没错」的因素能造成成倍差异。另一类错误更根本：输入分布选错——用随机数组测自适应排序、用近乎有序的数据测哈希，精确地测着一个不存在的负载。单次运行下结论、不报方差、两个实现在不同机器或编译选项上比、只测一个规模就用两点外推渐近，每一条都在评审里见过。</p><p><span class="marginnote">术语翻译：IQR（四分位距）就是用「切掉最低四分之一和最高四分之一后量剩下那段的宽度」的手段来做「不被极端样本绑架地报告波动」的事。它对离群值不敏感——一个 145 ms 的毛刺拉不宽 IQR，却能把均值拽高一大截。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定输入。三种都要有：随机（平均水平）、对抗（最坏情况验收）、真实 trace（部署预期），分布写进实验记录。规模做扫描，不取孤立点：log-log 图上斜率对得上理论阶（见<a href="/cs/asymptotic-notation">渐近记号</a>），才算真懂了这条曲线。</p><p>定测量。随机算法先干测操作计数（种子配对，<a href="/cs/amortized-analysis">摊还分析</a>式的记账口径），wall-clock 只作最后一步；计时用多个独立进程，报中位数与四分位距。</p><p>定环境。锁频率或记录频率、绑核、预热与冷测分开；编译选项与库版本写进结论——换任何一项，结论作废重跑。</p><p>定判读。比较的是分布，不是两个数：差距小于噪声区间就写「未分辨」，不许写成胜负。</p>',11)),(B(),r(s,null,{default:e(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%AE%9A%E8%BE%93%E5%85%A5%EF%BC%9A%E9%9A%8F%E6%9C%BA%20%2F%20%E5%AF%B9%E6%8A%97%20%2F%20%E7%9C%9F%E5%AE%9E%20trace%22%5D%20--%3E%20SWEEP%5B%22%E8%A7%84%E6%A8%A1%E6%89%AB%E6%8F%8F%EF%BC%9Alog-log%20%E9%AA%8C%E6%96%9C%E7%8E%87%22%5D%0A%20%20SWEEP%20--%3E%20COUNT%5B%22%E5%B9%B2%E6%B5%8B%EF%BC%9A%E6%93%8D%E4%BD%9C%E8%AE%A1%E6%95%B0%EF%BC%8C%E7%A7%8D%E5%AD%90%E9%85%8D%E5%AF%B9%22%5D%0A%20%20COUNT%20--%3E%20TIME%5B%22%E8%AE%A1%E6%97%B6%EF%BC%9A%E7%8B%AC%E7%AB%8B%E8%BF%9B%E7%A8%8B%EF%BC%8C%E4%B8%AD%E4%BD%8D%E6%95%B0%20%2B%20IQR%22%5D%0A%20%20TIME%20--%3E%20JUDGE%5B%22%E5%88%A4%E8%AF%BB%EF%BC%9A%E5%88%86%E5%B8%83%E5%AF%B9%E5%88%86%E5%B8%83%EF%BC%8C%E5%99%AA%E5%A3%B0%E5%86%85%E5%8D%B3%E6%9C%AA%E5%88%86%E8%BE%A8%22%5D%0A%20%20JUDGE%20--%3E%20REP%5B%22%E7%BB%93%E8%AE%BA%E9%99%84%E7%8E%AF%E5%A2%83%E4%B8%8E%E7%89%88%E6%9C%AC%E8%AE%B0%E5%BD%95%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"为什么中位数与四分位距：性能分布常是多峰——垃圾回收与频率迁移把样本堆成两个稳定模式，均值可能落在两个峰之间无人到达的位置；中位数对应真实工作模式，四分位距暴露离散度。为什么独立进程：同进程里上一轮留下的缓存内容、分支预测器状态与分配器布局会喂养下一轮，序贯复用进程的测量互相污染。为什么扫描能区分两类优化：常数优化平移曲线，渐近改进改斜率，两点测量既分不出这两者，还会把拟合外推成笑话。为什么种子配对减方差：配对差把共同的输入项消掉，剩下的方差只来自硬币——这是上一课留下诺言的兑现。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"Mytkowicz 等 2009 的标题即结论：「没做任何明显错误的事，却产出错误数据」——同一份代码，仅环境变量表大小或链接顺序不同，测得的性能差可达数倍。算法比较先赢下环境，再谈输赢。")],-1)),E[6]||(E[6]=a("p",null,"方法一节的图回答「一次基准按什么顺序做」，下面这张回答另一个问题：拿到扫描数据后，怎么区分「常数优化」和「渐近改进」这两种截然不同的赢法。",-1)),(B(),r(s,null,{default:e(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E4%B8%A4%E7%BB%84%E5%AE%9E%E7%8E%B0%E7%9A%84%E8%A7%84%E6%A8%A1%E6%89%AB%E6%8F%8F%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20LL%5B%22%E7%94%BB%20log-log%20%E5%9B%BE%2C%20%E9%80%90%E6%AE%B5%E7%9C%8B%E6%96%9C%E7%8E%87%22%5D%0A%20%20LL%20--%3E%20C%7B%22%E6%96%9C%E7%8E%87%E7%9B%B8%E5%90%8C%2C%20%E6%9B%B2%E7%BA%BF%E6%95%B4%E4%BD%93%E4%B8%8B%E7%A7%BB%3F%22%7D%0A%20%20C%20--%20%22%E6%98%AF%22%20--%3E%20K%5B%22%E5%B8%B8%E6%95%B0%E4%BC%98%E5%8C%96%3A%20%E5%90%8C%E9%98%B6%E6%9B%B4%E5%BF%AB%2C%20%E5%A4%A7%20n%20%E6%94%B6%E7%9B%8A%E5%8D%A0%E6%AF%94%E9%80%92%E5%87%8F%22%5D%0A%20%20C%20--%20%22%E5%90%A6%22%20--%3E%20S%7B%22%E6%96%9C%E7%8E%87%E5%8F%98%E4%BA%86%3F%22%7D%0A%20%20S%20--%20%22%E6%98%AF%22%20--%3E%20A%5B%22%E6%B8%90%E8%BF%91%E6%94%B9%E8%BF%9B%3A%20%E5%A4%A7%20n%20%E5%BF%85%E7%84%B6%E5%8F%8D%E8%B6%85%2C%20%E4%BA%A4%E7%82%B9%E8%A6%81%E6%A0%87%E5%87%BA%E6%9D%A5%22%5D%0A%20%20S%20--%20%22%E4%B8%8D%E7%A1%AE%E5%AE%9A%22%20--%3E%20M%5B%22%E7%82%B9%E5%A4%AA%E5%B0%91%3A%20%E8%A1%A5%E6%89%AB%E6%8F%8F%2C%20%E4%B8%8D%E8%AE%B8%E4%B8%A4%E7%82%B9%E5%A4%96%E6%8E%A8%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=o('<p><span class="marginnote">数字实例：十次运行得到 98、99、99、100、100、100、101、102、140、145 ms——均值约 108，被两个毛刺拉高了 8%；中位数 100 才是真实工作模式。报「中位数 100 ms、IQR 约 2 ms」远比只报一个「平均 108 ms」诚实。</span></p><p><span class="marginnote">常见误区：初学者看到「平均快了 3%」就宣布赢家；若这 3% 落在四分位距重叠的噪声区间里，正确结论是「未分辨」。另一个误区是拿两个规模点外推渐近——像量了 6 岁和 7 岁的身高就线性推算成年身高，发育拐点一改斜率，外推就成了笑话。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>微基准测的是片段；真实负载下的分配与调用模式是另一个系统，外推必须声明。为基准过拟合——对 benchmark 的输入特化、预取正好命中的数据——是作弊不是优化，评审要能识别。基准不替代正确性测试：快而错没有意义，随机算法的边界用例照钉。本课只管「一次比较的效力」；持续的性能监控、线上回归与容量，是性能工程案例课的主题，此处不展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三定先行：定输入分布、定测量协议、定环境；结论里写环境，否则不可复现。</li><li>随机算法先数操作再计时，种子配对消掉输入项的方差。</li><li>报中位数与四分位距；差距落在噪声区间内写「未分辨」，不判胜负。</li><li>规模扫描区分常数与渐近：平移对斜率，两点外推不可信。</li><li>出处：Mytkowicz et al., <em>Producing Wrong Data Without Doing Anything Obviously Wrong!</em>, ASPLOS 2009；Georges, Buytaert, and Eeckhout, OOPSLA 2007。</li></ul>',6))])}const g=n(p,[["render",m]]);export{f as __pageData,g as default};
